SELECT game_id AS "gameId", listener_id AS "listenerId", match_mode_type_id AS "matchModeTypeId", type_id AS "typeId", change_revision AS "changeRevision", updated_at AS "updatedAt" FROM public.listener_match_types WHERE game_id = #{gameId}
AND listener_id = #{listenerId}
ORDER BY listener_id, match_mode_type_id, type_id

 SELECT
game_id AS "gameId",
listener_id AS "listenerId",
match_mode_type_id AS "matchModeTypeId",
type_id AS "typeId",
change_revision AS "changeRevision",
updated_at AS "updatedAt"
 FROM public.listener_match_types
 WHERE game_id = #{gameId}
   AND listener_id = #{listenerId}
   AND match_mode_type_id = #{matchModeTypeId}
   AND type_id = #{typeId}
